CREATE TABLE measurements (
  -- Generated by the app (randomUUID), like experiments and samples.
  id uuid PRIMARY KEY,
  sample_id uuid NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
  -- double precision is returned by `pg` as a JS number (NUMERIC would be a string).
  value double precision NOT NULL,
  unit text NOT NULL,
  measurement_type text NOT NULL,
  -- When the measurement was taken; defaults to the time it was recorded.
  measured_at timestamp with time zone NOT NULL DEFAULT now()
);

-- A sample can have many measurements, including repeats of the same type
-- over time. This index serves "measurements for a sample, in time order"
-- and makes ON DELETE CASCADE from samples fast.
CREATE INDEX measurements_sample_id_measured_at_idx
  ON measurements (sample_id, measured_at, id);
